    self.started = true;
    if maximum_items == 0 {
        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
    }
    if self.active.is_none() {
        let step = self.take_next_owner(store, maximum_bytes)?;
