                Some(owner) => Ok(Self::retain(&mut self.active, Some(owner))),
                None => {
                    self.phase = ArtifactStoreCursorDisposerPhase::TailSnapshot;
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
